namespace sv_a013ccfb9d154d03a14e1441e38bf438.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for a warehouse.
/// Fires OnChange when new data arrives so all subscribed components update.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private static readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling every 10 seconds. Multiple callers increment a subscriber count;
    /// polling begins on the first subscriber.
    /// </summary>
    public void StartPolling(string warehouseId, Func<Task> invokeAsync)
    {
        _subscriberCount++;
        if (_subscriberCount > 1)
            return; // Already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, invokeAsync, _cts.Token);
    }

    /// <summary>
    /// Decrements subscriber count. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Allows updating the warehouse being polled (e.g., when the user switches warehouses).
    /// Restarts the poll loop with the new warehouse ID.
    /// </summary>
    public void RestartPolling(string warehouseId, Func<Task> invokeAsync)
    {
        if (_subscriberCount > 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();

            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

            _ = PollLoopAsync(warehouseId, invokeAsync, _cts.Token);
        }
    }

    private async Task PollLoopAsync(string warehouseId, Func<Task> invokeAsync, CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync(warehouseId, invokeAsync);

        while (!ct.IsCancellationRequested && _timer is not null)
        {
            try
            {
                if (await _timer.WaitForNextTickAsync(ct))
                {
                    await FetchAndNotifyAsync(warehouseId, invokeAsync);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync(string warehouseId, Func<Task> invokeAsync)
    {
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        // Notify all subscribers — they must wrap StateHasChanged in InvokeAsync
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

