@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseState> WarehouseSource
@using sv_a013ccfb9d154d03a14e1441e38bf438.Services

<select class="form-select form-select-sm" style="width: 200px;"
        value="@_selectedId" @onchange="OnWarehouseChanged">
    @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    private string _selectedId = "warehouse-a";

    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
        {
            _selectedId = Warehouse.SelectedWarehouseId;
        }
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "warehouse-a";
        var match = WarehouseState.AvailableWarehouses.FirstOrDefault(w => w.Id == newId);

        var newState = new WarehouseState
        {
            SelectedWarehouseId = match.Id ?? newId,
            SelectedWarehouseName = match.Name ?? newId
        };

        _selectedId = newState.SelectedWarehouseId;
        await WarehouseSource.NotifyChangedAsync(newState);
    }
}

