@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_a013ccfb9d154d03a14e1441e38bf438.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@Warehouse?.SelectedWarehouseName</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="card-text display-4 text-danger">@AlertService.LowStockCount</p>
                <small class="text-muted">Items below minimum level</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">Active</span>
                    <br />
                    <small class="text-muted">Refreshing every 10 seconds</small>
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private Action? _handler;
    private string _currentWarehouseId = "";

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;

        _currentWarehouseId = Warehouse?.SelectedWarehouseId ?? "warehouse-a";
        AlertService.StartPolling(_currentWarehouseId, () => InvokeAsync(StateHasChanged));
    }

    protected override void OnParametersSet()
    {
        // When warehouse changes via cascading parameter, restart polling for new warehouse
        var newId = Warehouse?.SelectedWarehouseId ?? "warehouse-a";
        if (newId != _currentWarehouseId)
        {
            _currentWarehouseId = newId;
            AlertService.RestartPolling(_currentWarehouseId, () => InvokeAsync(StateHasChanged));
        }
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnChange -= _handler;
        }
        AlertService.StopPolling();
    }
}

